import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeAggregateCompiler.UNKNOWN;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeAggregateCompiler.slotsOf;

import java.io.IOException;
import java.util.concurrent.atomic.AtomicLong;

import org.eclipse.rdf4j.common.annotation.Experimental;

/**
 * Build-once mark join for existence-only probes over a general {@link SlotPlan} (three-tier parity plan, Milestone 5).
 * Single-pattern subqueries already have their mark tier ({@code PatternMembershipProbe}, and above it the M2 adjacency
 * semijoin); this class is the same idea for the compiled multi-operator subplans those tiers cannot serve: the
 * {@code ExistsFilter} EXISTS / NOT EXISTS subplans and the independent MINUS right side, both of which today re-run
 * the whole subplan once per distinct memo key. After a distinct-miss threshold the subplan is swept ONCE with the
 * correlated key slots unbound, every produced key tuple is marked in the arity-adaptive {@link KeyedMatches} store
 * (presence only), and all later probes answer in O(1). Soundness leans on the same contract as the per-key memo — the
 * caller only creates a probe when {@code memoReadMask} names the slot set that fully determines the subplan's rows —
 * plus runtime aborts: a swept row that leaves a key slot unbound (it would match any probe) abandons the mark and the
 * per-row path keeps serving. Marks never touch the outer stream, so bag cardinality is preserved by construction.
 * <p>
 * MINUS mode reproduces the independent-evaluation semantics of {@code MinusCursor.openIndependentAndCheckRight}: keys
 * are the algebraically shared slots, a right solution binding none of them removes nothing unless base bindings make
 * every left row compatible (then it removes everything), and a solution binding a strict subset aborts to the boxed
 * nested loop. Kill switch: {@value #ENABLED_PROPERTY} (default off pending the paired benchmark gate).
 */
@Experimental
final class SubplanMarkProbe {
	static final String ENABLED_PROPERTY = "rdf4j.lmdb.markJoin.enabled";
	static final String MISS_THRESHOLD_PROPERTY = "rdf4j.lmdb.markJoin.missThreshold";
	static final String MAX_KEYS_PROPERTY = "rdf4j.lmdb.markJoin.maxKeys";
	static final String MAX_SWEEP_ROWS_PROPERTY = "rdf4j.lmdb.markJoin.maxSweepRows";

	/** Committed mark builds (one full key-unbound sweep each). Test witness. */
	static final AtomicLong SWEEP_BUILDS = new AtomicLong();
	/** Probes answered from a committed mark table. Test witness. */
	static final AtomicLong SWEEP_PROBES = new AtomicLong();
	/** Sweeps abandoned mid-build (unbound key slot, cap overshoot, IO); the per-row path keeps serving. */
	static final AtomicLong SWEEP_ABORTS = new AtomicLong();

	private final SlotPlan plan;
	private final int[] candidateSlots;
	private final long candidateMask;
	private final boolean minusSemantics;
	private final long minThresholdMisses;

	private long misses;
	private int[] keySlots;
	/** Bound shape over the candidate slots captured at build time; probes with a different shape decline. */
	private long buildShapeMask;
	private KeyedMatches marks;
	/** MINUS only: a right solution binding no shared slot is compatible with every left row via base bindings. */
	private boolean removesAll;
	private boolean built;
	private boolean disabled;

	private SubplanMarkProbe(SlotPlan plan, int[] candidateSlots, boolean minusSemantics) {
		this.plan = plan;
		this.candidateSlots = candidateSlots;
		long mask = 0L;
		for (int slot : candidateSlots) {
			mask |= 1L << slot;
		}
		this.candidateMask = mask;
		this.minusSemantics = minusSemantics;
		this.minThresholdMisses = Math.max(1L, Long.getLong(MISS_THRESHOLD_PROPERTY, 64L));
	}

	static boolean enabled() {
		return Boolean.getBoolean(ENABLED_PROPERTY);
	}

	static void resetMetrics() {
		SWEEP_BUILDS.set(0L);
		SWEEP_PROBES.set(0L);
		SWEEP_ABORTS.set(0L);
	}

	/**
	 * Mark probe for an EXISTS / NOT EXISTS subplan whose outcome is fully determined by {@code memoSlots} (the
	 * caller's {@code memoReadMask} verdict). The correlated key shape is captured at build time from the live row:
	 * bound non-base memo slots key the table, unbound ones stay existentially quantified in the sweep.
	 */
	static SubplanMarkProbe tryCreateExists(SlotPlan subPlan, int[] memoSlots) {
		if (!enabled() || memoSlots == null || memoSlots.length == 0 || subPlan instanceof PatternPlan) {
			return null;
		}
		return new SubplanMarkProbe(subPlan, memoSlots, false);
	}

	/**
	 * Mark probe for the independently evaluated MINUS right side, keyed on the algebraically shared slots. The caller
	 * must have a non-negative {@code memoReadMask} for the right plan (same gate as its per-key memo).
	 */
	static SubplanMarkProbe tryCreateMinus(SlotPlan right, long sharedMask) {
		if (!enabled() || sharedMask == 0L || right instanceof PatternPlan) {
			return null;
		}
		return new SubplanMarkProbe(right, slotsOf(sharedMask), true);
	}

	/** 1 = subplan has a compatible solution, 0 = provably none, -1 = not answerable here (use the per-row path). */
	int test(RowState row) {
		if (disabled) {
			return -1;
		}
		if (!built) {
			if (++misses <= minThresholdMisses) {
				return -1;
			}
			try {
				build(row);
			} catch (IOException | RuntimeException problem) {
				abort();
				return -1;
			}
			if (!built) {
				return -1;
			}
		}
		return probe(row);
	}

	private int probe(RowState row) {
		if (minusSemantics && removesAll) {
			SWEEP_PROBES.incrementAndGet();
			return 1;
		}
		if ((row.boundMask() & candidateMask) != buildShapeMask) {
			return -1;
		}
		SWEEP_PROBES.incrementAndGet();
		return marks.find(row.slots, keySlots) >= 0 ? 1 : 0;
	}

	private void build(RowState row) throws IOException {
		long keyMask = minusSemantics
				? candidateMask
				: candidateMask & row.boundMask() & ~row.baseBindingMask;
		if (keyMask == 0L || (keyMask & ~plan.producedMask()) != 0L) {
			// constant outcome (the memo's one entry serves) or a filter-only key the sweep cannot re-enumerate
			disabled = true;
			return;
		}
		this.keySlots = slotsOf(keyMask);
		this.buildShapeMask = minusSemantics ? candidateMask : row.boundMask() & candidateMask;
		long clearMask = minusSemantics
				? row.boundMask() & ~row.baseBindingMask
				: keyMask;
		boolean baseCompatible = minusSemantics
				&& (row.baseBindingMask != 0L || row.base.size() > Long.bitCount(row.baseBindingMask));
		long maxKeys = Long.getLong(MAX_KEYS_PROPERTY, 4_000_000L);
		long maxSweepRows = Long.getLong(MAX_SWEEP_ROWS_PROPERTY, 16_000_000L);
		int[] clearedSlots = new int[Long.bitCount(clearMask)];
		long[] clearedValues = new long[clearedSlots.length];
		int cleared = 0;
		for (long remaining = clearMask; remaining != 0L; remaining &= remaining - 1) {
			int slot = Long.numberOfTrailingZeros(remaining);
			clearedSlots[cleared] = slot;
			clearedValues[cleared] = row.replaceSlot(slot, UNKNOWN);
			cleared++;
		}
		KeyedMatches set = new KeyedMatches(keySlots.length, 1024);
		boolean complete = false;
		boolean allRemoved = false;
		int mark = row.mark();
		try (RowCursor sweep = plan.open(row)) {
			long total = 0L;
			while (true) {
				if (!sweep.next()) {
					complete = true;
					break;
				}
				if (++total > maxSweepRows || set.size() > maxKeys) {
					break;
				}
				int boundKeys = 0;
				for (int slot : keySlots) {
					if (row.slots[slot] != UNKNOWN) {
						boundKeys++;
					}
				}
				if (boundKeys == keySlots.length) {
					set.findOrInsert(row.slots, keySlots);
				} else if (minusSemantics && boundKeys == 0) {
					// disjoint-domain right solution: removes nothing on its own, everything via base bindings
					if (baseCompatible) {
						allRemoved = true;
						complete = true;
						break;
					}
				} else {
					// a partially bound key would match any probe value on its unbound slots
					break;
				}
			}
		} finally {
			row.rollback(mark);
			for (int i = cleared - 1; i >= 0; i--) {
				row.replaceSlot(clearedSlots[i], clearedValues[i]);
			}
		}
		if (!complete) {
			abort();
			return;
		}
		this.marks = set;
		this.removesAll = allRemoved;
		this.built = true;
		SWEEP_BUILDS.incrementAndGet();
	}

	private void abort() {
		disabled = true;
		marks = null;
		SWEEP_ABORTS.incrementAndGet();
	}
}
